import{_ as t,o,c as r,a5 as e}from"./chunks/framework.B5tqjWbr.js";const h=JSON.parse('{"title":"多项式轨迹规划测验","description":"","frontmatter":{"date":"2026-06-13T00:00:00.000Z","section":"电机控制","chapter":"motion-control","chapterTitle":"运动控制","chapterOrder":30,"category":"运动控制","source":"motor","visibility":"public","title":"多项式轨迹规划测验","tags":["motor-control"],"status":"learning","summary":"**问题:** 三次多项式和五次多项式分别能保证几阶连续性？","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/motion-control/MC-TP-03-assessment.md","filePath":"content/motor/motion-control/MC-TP-03-assessment.md","lastUpdated":null}'),n={name:"content/motor/motion-control/MC-TP-03-assessment.md"};function s(i,a,l,c,T,p){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="多项式轨迹规划测验" tabindex="-1">多项式轨迹规划测验 <a class="header-anchor" href="#多项式轨迹规划测验" aria-label="Permalink to &quot;多项式轨迹规划测验&quot;">​</a></h1><h3 id="第1题-中等-多项式连续性阶数-★★" tabindex="-1">第1题 [中等] - 多项式连续性阶数 ★★ <a class="header-anchor" href="#第1题-中等-多项式连续性阶数-★★" aria-label="Permalink to &quot;第1题 [中等] - 多项式连续性阶数 ★★&quot;">​</a></h3><p><strong>问题:</strong> 三次多项式和五次多项式分别能保证几阶连续性？</p><p><strong>参考答案:</strong> 三次多项式 q(t) = a₀ + a₁t + a₂t² + a₃t³ 有4个自由系数，可指定起点和终点的位置与速度共4个边界条件，因此能保证位置和速度的连续性（C¹连续），但加速度在端点处不连续。五次多项式 q(t) = a₀ + a₁t + a₂t² + a₃t³ + a₄t⁴ + a₅t⁵ 有6个自由系数，可指定起点和终点的位置、速度和加速度共6个边界条件，因此能保证位置、速度和加速度的连续性（C²连续），jerk在端点处不连续。连续性阶数 = 多项式阶数/2 - 1（取整）。</p><h3 id="第2题-较难-五次多项式用于伺服轨迹-★★★" tabindex="-1">第2题 [较难] - 五次多项式用于伺服轨迹 ★★★ <a class="header-anchor" href="#第2题-较难-五次多项式用于伺服轨迹-★★★" aria-label="Permalink to &quot;第2题 [较难] - 五次多项式用于伺服轨迹 ★★★&quot;">​</a></h3><p><strong>问题:</strong> 为什么五次多项式比三次多项式更适合伺服轨迹规划？</p><p><strong>参考答案:</strong> 伺服系统对力矩连续性有严格要求，而力矩与加速度成正比。三次多项式只能保证C¹连续（位置和速度连续），加速度在段间不连续，意味着力矩突变，会导致：（1）电流环需要跟踪阶跃电流指令，产生跟踪误差；（2）机械冲击和振动；（3）激发结构共振。五次多项式保证C²连续（加速度连续），力矩平滑过渡，避免了上述问题。此外，五次多项式可以指定端点加速度，使得轨迹与前后段的速度和加速度都匹配，适合多段拼接。代价是五次多项式可能在中间段出现超调（overshoot），需要检查轨迹是否超出物理约束。</p><h3 id="第3题-困难-五次多项式边界条件方程-★★★★" tabindex="-1">第3题 [困难] - 五次多项式边界条件方程 ★★★★ <a class="header-anchor" href="#第3题-困难-五次多项式边界条件方程-★★★★" aria-label="Permalink to &quot;第3题 [困难] - 五次多项式边界条件方程 ★★★★&quot;">​</a></h3><p><strong>问题:</strong> 给定起点q0=0, v0=0, a0=0和终点qf=1, vf=0, af=0，写出五次多项式的边界条件方程。</p><p><strong>参考答案:</strong> 设五次多项式 q(t) = a₀ + a₁t + a₂t² + a₃t³ + a₄t⁴ + a₅t⁵，时间区间[0, T]。边界条件：q(0)=0 → a₀=0；q&#39;(0)=0 → a₁=0；q&#39;&#39;(0)=0 → 2a₂=0 → a₂=0。q(T)=1 → a₃T³ + a₄T⁴ + a₅T⁵ = 1；q&#39;(T)=0 → 3a₃T² + 4a₄T³ + 5a₅T⁴ = 0；q&#39;&#39;(T)=0 → 6a₃T + 12a₄T² + 20a₅T³ = 0。化简后三个方程为：a₃T³ + a₄T⁴ + a₅T⁵ = 1，3a₃ + 4a₄T + 5a₅T² = 0，6a₃ + 12a₄T + 20a₅T² = 0。解得：a₃ = 10/T³, a₄ = -15/T⁴, a₅ = 6/T⁵。最终轨迹：q(t) = 10(t/T)³ - 15(t/T)⁴ + 6(t/T)⁵。</p><h3 id="第4题-较难-多项式与s曲线对比-★★★" tabindex="-1">第4题 [较难] - 多项式与S曲线对比 ★★★ <a class="header-anchor" href="#第4题-较难-多项式与s曲线对比-★★★" aria-label="Permalink to &quot;第4题 [较难] - 多项式与S曲线对比 ★★★&quot;">​</a></h3><p><strong>问题:</strong> 多项式轨迹与S曲线轨迹各自的优势和劣势是什么？</p><p><strong>参考答案:</strong> 多项式轨迹优势：（1）数学表达简洁，解析解易于实时计算；（2）通过边界条件自然保证连续性，无需分段判断；（3）适合空间路径约束场景（如关节空间插值）；（4）参数化灵活，可指定任意端点状态。劣势：（1）无法显式约束速度/加速度/jerk的极值，可能产生超调；（2）不保证时间最优，通常比S曲线耗时更长；（3）高阶多项式可能出现Runge现象（中间段振荡）。S曲线轨迹优势：（1）显式约束v_max、a_max、jerk，物理意义清晰；（2）接近时间最优；（3）不会出现超调问题。劣势：（1）仅适用于点到点运动，不适合空间路径插值；（2）七段式逻辑复杂，退化情况多；（3）只能保证C¹或C²连续，无法保证更高阶连续性。</p>',13)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
